import { tags } from "typia";

/**
 * Effective filter configuration used when generating a refund analytics
 * summary.
 *
 * This structure echoes the original request filters but may also include
 * derived or defaulted values that were applied by the backend, making the
 * analytical result self-describing.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallAnalyticsRefundFilters = {
  /**
   * Grouping dimension actually used for the analytics, copied from the
   * request or defaulted if omitted.
   */
  groupBy?: "reason" | "seller" | "status" | "none" | undefined;

  /**
   * Minimum refunded amount threshold that was applied. May be null if no
   * threshold was used.
   */
  minRefundAmount?: (number & tags.Minimum<0>) | undefined;

  /**
   * Business-level refund or case types that were explicitly included in the
   * analytics. Empty when no inclusion filter was applied.
   */
  includeCaseTypes?:
    | ("policy" | "goodwill" | "fraud" | "systemError" | "other")[]
    | undefined;

  /**
   * Business-level refund or case types that were explicitly excluded from
   * the analytics. Empty when no exclusion filter was applied.
   */
  excludeCaseTypes?:
    | ("policy" | "goodwill" | "fraud" | "systemError" | "other")[]
    | undefined;

  /**
   * Seller identifiers that were used to restrict analytics, if any. Empty
   * when analytics covers all sellers.
   */
  sellerIds?: (string & tags.Format<"uuid">)[] | undefined;

  /**
   * Structured refund reason codes that were used to restrict the analytics,
   * if any.
   */
  reasonCodes?: string[] | undefined;

  /**
   * Flag indicating whether refunds associated with disputes were included in
   * the analytics.
   */
  includeDisputes: boolean;

  /**
   * Flag indicating whether refunds related to chargeback cases were included
   * in the analytics.
   */
  includeChargebacks: boolean;
};
